insert into public.products (id, name, kor_name, category_id, sub_type, gender, template, texture, base_image, image_colors, price, sale_price, sizes, colors, badge, fit, fabric, occasions, styles, description, material, care, is_photo, status, sold_count, likes_count, created_at) values ('k01', 'Hoodie oversize Cloud', '클라우드 후디', 'tops', 'top', 'unisex', 'hoodie', 'fleece', 'k01', array['lav','melange','black']::text[], 690000, null, array['S','M','L','XL']::text[], array['lav','melange','black']::text[], 'best', 'oversized', array[3,2,1,1]::smallint[], array['weekend','travel']::text[], array['casual','minimal']::text[], 'Hoodie nỉ bông dáng oversize, vai rơi, mũ hai lớp và túi kangaroo rộng. Thân áo dài vừa đủ để mặc cùng quần ống rộng.', '80% cotton, 20% polyester, nỉ bông 380 gsm', 'Giặt máy 30°C, lộn trái, không sấy nhiệt cao.', false, 'active', 2024, 4820, now() - interval '2592000 seconds');
insert into public.products (id, name, kor_name, category_id, sub_type, gender, template, texture, base_image, image_colors, price, sale_price, sizes, colors, badge, fit, fabric, occasions, styles, description, material, care, is_photo, status, sold_count, likes_count, created_at) values ('k02', 'Áo nỉ boxy Everyday', '데일리 맨투맨', 'tops', 'top', 'unisex', 'sweat', 'fleece', 'k02', array['mint','oat','navy']::text[], 590000, 490000, array['S','M','L','XL']::text[], array['mint','oat','navy']::text[], 'sale', 'oversized', array[2,2,1,1]::smallint[], array['weekend','travel','work']::text[], array['casual','minimal']::text[], 'Áo nỉ cổ tròn dáng boxy với đường chỉ chữ V ở cổ và bo gân dày. Giữ phom tốt sau nhiều lần giặt.', '80% cotton, 20% polyester, 320 gsm', 'Giặt máy 30°C, phơi ngang.', false, 'active', 970, 2310, now() - interval '4320000 seconds');
insert into public.products (id, name, kor_name, category_id, sub_type, gender, template, texture, base_image, image_colors, price, sale_price, sizes, colors, badge, fit, fabric, occasions, styles, description, material, care, is_photo, status, sold_count, likes_count, created_at) values ('k03', 'Cardigan len vặn thừng croptop', '크롭 케이블 가디건', 'tops', 'outer', 'unisex', 'cardigan', 'cable', 'k03', array['butter','sky','cream']::text[], 790000, null, array['S','M','L']::text[], array['butter','sky','cream']::text[], 'new', 'regular', array[2,3,2,1]::smallint[], array['date','work','weekend']::text[], array['romantic','minimal']::text[], 'Cardigan croptop đan vặn thừng mềm, cúc ngọc trai. Cài hết cúc để mặc như áo, hoặc mở ra khoác ngoài áo thun.', '60% cotton, 40% acrylic', 'Giặt tay nước lạnh, phơi ngang để giữ phom.', false, 'active', 690, 1640, now() - interval '518400 seconds');
insert into public.products (id, name, kor_name, category_id, sub_type, gender, template, texture, base_image, image_colors, price, sale_price, sizes, colors, badge, fit, fabric, occasions, styles, description, material, care, is_photo, status, sold_count, likes_count, created_at) values ('k04', 'Áo gile len cổ V', '소프트 니트 베스트', 'tops', 'vest', 'unisex', 'vest', 'knitfine', 'k04', array['pink','melange','black']::text[], 490000, null, array['One size']::text[], array['pink','melange','black']::text[], '', 'oversized', array[2,2,1,1]::smallint[], array['work','date']::text[], array['elegant','romantic']::text[], 'Áo gile len cổ V dệt mịn, dáng rộng để mặc chồng ngoài sơ mi hoặc áo thun. Một size cho nhiều dáng người.', '70% cotton, 30% nylon', 'Giặt tay, phơi ngang.', false, 'active', 410, 980, now() - interval '3456000 seconds');
insert into public.products (id, name, kor_name, category_id, sub_type, gender, template, texture, base_image, image_colors, price, sale_price, sizes, colors, badge, fit, fabric, occasions, styles, description, material, care, is_photo, status, sold_count, likes_count, created_at) values ('k05', 'Sơ mi Oxford oversize', '빅 옥스포드 셔츠', 'tops', 'top', 'unisex', 'shirt', 'oxford', 'k05', array['sky','white','pink']::text[], 550000, null, array['S','M','L','XL']::text[], array['sky','white','pink']::text[], 'best', 'oversized', array[1,1,2,1]::smallint[], array['work','date','weekend']::text[], array['minimal','elegant']::text[], 'Sơ mi Oxford dáng oversize, vạt bầu dài và một túi ngực. Càng giặt càng mềm.', '100% cotton Oxford', 'Giặt máy 40°C, ủi khi còn ẩm.', false, 'active', 1310, 3120, now() - interval '6048000 seconds');
insert into public.products (id, name, kor_name, category_id, sub_type, gender, template, texture, base_image, image_colors, price, sale_price, sizes, colors, badge, fit, fabric, occasions, styles, description, material, care, is_photo, status, sold_count, likes_count, created_at) values ('k06', 'Áo thun boxy dày dặn', '헤비 박스 티', 'tops', 'top', 'unisex', 'boxytee', 'jersey', 'k06', array['white','black','lav','mint']::text[], 290000, null, array['S','M','L','XL']::text[], array['white','black','lav','mint']::text[], 'best', 'oversized', array[2,2,1,1]::smallint[], array['weekend','travel','work']::text[], array['minimal','casual']::text[], 'Áo thun cotton 260 gsm dáng boxy, vai rơi. Đủ dày để mặc một lớp mà không lộ.', '100% cotton 260 gsm', 'Giặt máy 30°C, lộn trái.', false, 'active', 2930, 6980, now() - interval '8640000 seconds');
insert into public.products (id, name, kor_name, category_id, sub_type, gender, template, texture, base_image, image_colors, price, sale_price, sizes, colors, badge, fit, fabric, occasions, styles, description, material, care, is_photo, status, sold_count, likes_count, created_at) values ('k07', 'Áo khoác varsity Campus', '캠퍼스 바시티', 'outer', 'outer', 'unisex', 'varsity', 'wool', 'k07', array['navy','black']::text[], 1390000, null, array['S','M','L','XL']::text[], array['navy','black']::text[], 'new', 'oversized', array[3,1,1,2]::smallint[], array['weekend','date','party']::text[], array['casual']::text[], 'Áo khoác varsity vải pha len, tay áo phối màu, bo gân sọc và cúc bấm. Lót trần bông cho ngày lạnh.', '60% len, 40% polyester; tay áo giả da', 'Chỉ giặt khô.', false, 'active', 930, 2210, now() - interval '345600 seconds');
insert into public.products (id, name, kor_name, category_id, sub_type, gender, template, texture, base_image, image_colors, price, sale_price, sizes, colors, badge, fit, fabric, occasions, styles, description, material, care, is_photo, status, sold_count, likes_count, created_at) values ('k08', 'Áo phao ngắn Marshmallow', '마시멜로 숏패딩', 'outer', 'outer', 'unisex', 'puffer', 'nylon', 'k08', array['sky','black','cream']::text[], 1590000, 1290000, array['S','M','L','XL']::text[], array['sky','black','cream']::text[], 'sale', 'oversized', array[3,1,1,2]::smallint[], array['travel','weekend']::text[], array['casual','minimal']::text[], 'Áo phao dáng ngắn chần bông ngang, cổ đứng cao và khoá kéo hai chiều. Nhẹ, ấm và gấp gọn.', 'Vỏ nylon chống nước nhẹ, ruột bông polyester', 'Giặt tay nhẹ, phơi khô rồi vỗ cho bông phồng.', false, 'active', 1630, 3890, now() - interval '1728000 seconds');
